INSERT INTO feature VALUES('pattern-matching','types','Nested pattern matching','nominal-data','implemented','ordinary',NULL,'A match''s arms nest constructor and literal patterns, compiled into a decision tree of native eliminations; a match that writes its answer, `match e -> C { … }`, has its tree''s root ascribed it, so it synthesises where nothing states its type. A match in layout form writes `where` after its scrutinee, `match e where`, and its arms on the lines after it; one that writes no `where` is refused `OutOfFragment.BareArms`.','surface-parser surface-lowering surface-pretty','corpus/model/data/data-matched-arms.gandr corpus/model/control/eliminator-answers.gandr corpus/ledger/diagnostics/OutOfFragment.BareArms.gandr','corpus/ledger/features/pattern-matching.gandr',NULL);
